package org.pestinha.android;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.Build;
import org.json.*;
import java.util.*;

/** Local task state and one token-guarded alarm per open task. No neural memory writes. */
final class Tasks {
    static final String ACTION="org.pestinha.android.TASK",CONTROL="org.pestinha.android.TASK_CONTROL";
    static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("tasks",0);}
    static JSONArray list(Context c){try{return new JSONArray(prefs(c).getString("items","[]"));}catch(JSONException e){return new JSONArray();}}
    static JSONObject find(Context c,String id){JSONArray rows=list(c);for(int i=0;i<rows.length();i++){JSONObject t=rows.optJSONObject(i);if(t!=null&&Objects.equals(id,t.optString("id")))return t;}return null;}
    private static void persist(Context c,JSONObject task) throws Exception {JSONArray all=list(c),next=new JSONArray();boolean seen=false;for(int i=0;i<all.length();i++){JSONObject old=all.getJSONObject(i);if(old.getString("id").equals(task.getString("id"))){next.put(task);seen=true;}else next.put(old);}if(!seen){if(all.length()>=50)throw new IllegalStateException("Limite de 50 tarefas. Apague as concluídas para liberar espaço.");next.put(task);}if(!prefs(c).edit().putString("items",next.toString()).commit())throw new IllegalStateException("Não foi possível salvar a tarefa.");}
    static long daytime(long candidate){Calendar d=Calendar.getInstance();d.setTimeInMillis(candidate);int h=d.get(Calendar.HOUR_OF_DAY);if(h>=22){d.add(Calendar.DAY_OF_YEAR,1);d.set(Calendar.HOUR_OF_DAY,8);d.set(Calendar.MINUTE,0);d.set(Calendar.SECOND,0);d.set(Calendar.MILLISECOND,0);}else if(h<8){d.set(Calendar.HOUR_OF_DAY,8);d.set(Calendar.MINUTE,0);d.set(Calendar.SECOND,0);d.set(Calendar.MILLISECOND,0);}return d.getTimeInMillis();}
    static String kind(JSONObject t,long now){if(t.optString("status").equals("done"))return "none";if(now>=t.optLong("due"))return t.optBoolean("dueSent")?"overdue":"due";long before=t.optLong("due")-3600000;if(!t.optBoolean("beforeSent")&&before>t.optLong("created"))return t.optLong("checkAt",Long.MAX_VALUE)<before?"check":"before";return t.optLong("checkAt",Long.MAX_VALUE)<t.optLong("due")?"check":"due";}
    static long when(JSONObject t,long now){String kind=kind(t,now);long at=kind.equals("none")?Long.MAX_VALUE:kind.equals("due")?t.optLong("due"):kind.equals("before")?t.optLong("due")-3600000:kind.equals("overdue")?t.optLong("overdueAt",daytime(now+86400000)):t.optLong("checkAt",Long.MAX_VALUE);return Math.max(at,t.optLong("snoozeUntil",0));}
    static Intent broadcast(Context c,JSONObject t,String action){return new Intent(c,AssistantReceiver.class).setAction(action).setData(Uri.parse("pestinha://task/"+t.optString("id"))).putExtra("task",t.optString("id")).putExtra("token",t.optString("token"));}
    static PendingIntent pending(Context c,JSONObject t){return PendingIntent.getBroadcast(c,0,broadcast(c,t,ACTION),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    static void arm(Context c,JSONObject t){if(t.optString("status").equals("done")){c.getSystemService(AlarmManager.class).cancel(pending(c,t));return;}long at=Math.max(System.currentTimeMillis()+1000,when(t,System.currentTimeMillis()));AlarmManager m=c.getSystemService(AlarmManager.class);if(LocalAssistant.precise(c))try{m.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pending(c,t));return;}catch(SecurityException ignored){}m.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pending(c,t));}
    static synchronized JSONObject save(Context c,String id,String title,long due,int hours) throws Exception {
        title=title.trim();if(title.isEmpty()||title.length()>160)throw new IllegalArgumentException("Escreva uma tarefa de até 160 caracteres.");long now=System.currentTimeMillis();if(due<=now)throw new IllegalArgumentException("Escolha um prazo futuro.");if(hours!=0&&hours!=1&&hours!=2&&hours!=4&&hours!=24)throw new IllegalArgumentException("Intervalo inválido.");
        JSONObject t=id==null?null:find(c,id);if(id!=null&&t==null)throw new IllegalStateException("A tarefa não existe mais.");if(t==null)t=new JSONObject().put("id",UUID.randomUUID().toString()).put("character",MemoryActivity.petId(c)).put("status","todo");
        t.put("title",title).put("due",due).put("created",now).put("hours",hours).put("beforeSent",false).put("dueSent",false).put("snoozeUntil",0).put("checkAt",hours==0?Long.MAX_VALUE:daytime(now+hours*3600000L)).put("token",UUID.randomUUID().toString());persist(c,t);dismiss(c,t.optString("id"));arm(c,t);return t;
    }
    static synchronized void update(Context c,String id,String status) throws Exception {JSONObject t=find(c,id);if(t==null)return;if(!Arrays.asList("doing","done","snooze").contains(status))return;if(t.optString("status").equals("done"))return;long now=System.currentTimeMillis();if(status.equals("snooze"))t.put("snoozeUntil",now+1800000);else {t.put("status",status);if(status.equals("doing")&&t.optInt("hours")>0)t.put("checkAt",daytime(now+t.optInt("hours")*3600000L));}t.put("updated",now).put("token",UUID.randomUUID().toString());persist(c,t);dismiss(c,id);arm(c,t);}
    static void dismiss(Context c,String id){c.getSystemService(NotificationManager.class).cancel("task:"+id,1);}
    static synchronized void delete(Context c,String id) throws Exception {JSONObject t=find(c,id);if(t==null)return;c.getSystemService(AlarmManager.class).cancel(pending(c,t));JSONArray next=new JSONArray(),all=list(c);for(int i=0;i<all.length();i++){JSONObject row=all.getJSONObject(i);if(!id.equals(row.optString("id")))next.put(row);}if(!prefs(c).edit().putString("items",next.toString()).commit())throw new IllegalStateException("Falha ao apagar tarefa.");dismiss(c,id);}
    static String message(Context c,JSONObject t,String kind){String lead=kind.equals("before")?"Falta cerca de uma hora para o prazo: ":kind.equals("due")?"Chegou o prazo de entrega: ":kind.equals("overdue")?"O prazo passou. Vamos concluir ou reorganizar? ":"Como está o andamento? ";String name=Characters.name(c,t.optString("character","bryan"));return name+": "+(t.optString("character").equals("mimir")?"Hmpf. ":"")+lead+t.optString("title")+". Toque para atualizar.";}
    static synchronized void fire(Context c,String id,String token) throws Exception {
        JSONObject t=find(c,id);if(t==null||!Objects.equals(token,t.optString("token"))||t.optString("status").equals("done"))return;long now=System.currentTimeMillis();if(when(t,now)>now+1000){arm(c,t);return;}String kind=kind(t,now);
        if(kind.equals("due")||kind.equals("overdue"))t.put("dueSent",true).put("overdueAt",daytime(now+86400000L));if(kind.equals("before"))t.put("beforeSent",true);int hours=t.optInt("hours");t.put("checkAt",hours==0?Long.MAX_VALUE:daytime(now+hours*3600000L)).put("snoozeUntil",0).put("lastNotice",now).put("token",UUID.randomUUID().toString());persist(c,t);arm(c,t);
        String text=message(c,t,kind);LocalAssistant.channel(c);Intent open=new Intent(c,TaskActivity.class).setData(Uri.parse("pestinha://task/"+id)).putExtra("task",id);PendingIntent content=PendingIntent.getActivity(c,0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
        Notification.Builder n=new Notification.Builder(c,LocalAssistant.CHANNEL).setSmallIcon(R.drawable.ic_notification).setContentTitle("Pestinha • sua tarefa").setContentText(text).setStyle(new Notification.BigTextStyle().bigText(text)).setContentIntent(content).setAutoCancel(true).setVisibility(Notification.VISIBILITY_PRIVATE);
        for(String action:new String[]{"doing","done","snooze"}){Intent i=broadcast(c,t,CONTROL).setData(Uri.parse("pestinha://task/"+id+"/"+action)).putExtra("control",action);PendingIntent pi=PendingIntent.getBroadcast(c,0,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);n.addAction(new Notification.Action.Builder(null,action.equals("doing")?"Comecei":action.equals("done")?"Concluir":"Adiar aviso 30 min",pi).build());}
        if(Build.VERSION.SDK_INT<33||c.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)==android.content.pm.PackageManager.PERMISSION_GRANTED)try{if(LocalAssistant.notificationsAllowed(c))c.getSystemService(NotificationManager.class).notify("task:"+id,1,n.build());}catch(SecurityException ignored){}
        PetService.taskNotice(text,id,false);
    }
    static synchronized void control(Context c,String id,String token,String action) throws Exception {JSONObject t=find(c,id);if(t!=null&&Objects.equals(token,t.optString("token")))update(c,id,action);}
    static void rearm(Context c){JSONArray all=list(c);for(int i=0;i<all.length();i++){JSONObject t=all.optJSONObject(i);if(t!=null)try{arm(c,t);}catch(RuntimeException ignored){}}}
    static boolean invitationDue(Context c,long now){if(!prefs(c).getBoolean("invite",true))return false;Calendar day=Calendar.getInstance();day.setTimeInMillis(now);day.set(Calendar.HOUR_OF_DAY,0);day.set(Calendar.MINUTE,0);day.set(Calendar.SECOND,0);day.set(Calendar.MILLISECOND,0);return prefs(c).getLong("invitedAt",0)<day.getTimeInMillis();}
}
